import React from 'react';
import { BrowserRouter, Routes, Route, } from "react-router-dom";
import Homepage from '../HomePage/HomePage'
import TeamSinglePage from '../TeamSinglePage/TeamSinglePage';
import ProjectSinglePage from '../ProjectSinglePage/ProjectSinglePage';
import PricingPage from '../PricingPage/PricingPage';
import ContactPage from '../ContactPage/ContactPage';
import ErrorPage from '../ErrorPage/ErrorPage';

const AllRoute = () => {

  return (
    <div className="App">
      <BrowserRouter>
        <Routes>
          <Route path="/" element={<Homepage />} />
          <Route path="home" element={<Homepage />} />
          <Route path="about" element={<TeamSinglePage />} />
          <Route path="portfolio" element={<ProjectSinglePage />} />
          <Route path="pricing" element={<PricingPage />} />
          <Route path="team-single/:slug" element={<TeamSinglePage />} />
          <Route path="project-single/:slug" element={<ProjectSinglePage />} />
          <Route path="404" element={<ErrorPage />} />
          <Route path="contact" element={<ContactPage />} />
        </Routes>
      </BrowserRouter>

    </div>
  );
}

export default AllRoute;
